  function controls(b){
    var btns=[];
    if(b.archived){
      btns.push('<button class="btn" data-act="restore" data-id="'+b.id+'">↩ Restore</button>');
    }else{
      if(!b.read) btns.push('<button class="btn primary" data-act="read" data-id="'+b.id+'">✓ Mark read</button>');
