      btns.push('<button class="btn" data-act="archive" data-id="'+b.id+'">🗄 Archive</button>');
    }
    return '<div class="ctrls">'+btns.join('')+'</div>';
  }

  function badge(b){
    var read=b.read?'<span class="sb read">Read</span>':'<span class="sb unread">Unread</span>';
